// Clean-room explicit-choice profile of randomized vector scheduling.
#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
namespace {constexpr std::size_t N=16,M=8,D=4,INPUT=83,FIELDS=35;void put(std::uint8_t*out,std::size_t at,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(std::size_t i=0;i<8;++i){out[at+i]=static_cast<std::uint8_t>(b&255u);b>>=8;}}}
extern "C" std::int64_t vector_scheduling(const std::int64_t*input,std::size_t length,std::uint8_t*output,std::size_t capacity){if(!input||length<3||length>INPUT)return -1;auto n64=input[0],m64=input[1],d64=input[2];if(n64<1||n64>16||m64<1||m64>8||d64<1||d64>4||length!=3+static_cast<std::size_t>(n64)+static_cast<std::size_t>(n64*d64))return -1;auto n=static_cast<std::size_t>(n64),m=static_cast<std::size_t>(m64),d=static_cast<std::size_t>(d64);for(std::size_t j=0;j<n;++j)if(input[3+j]<0||input[3+j]>=m64)return -1;for(std::size_t i=0;i<n*d;++i)if(input[3+n+i]<0||input[3+n+i]>1000)return -1;std::array<std::array<std::int64_t,D>,M> load{};for(std::size_t j=0;j<n;++j){auto machine=static_cast<std::size_t>(input[3+j]);for(std::size_t q=0;q<d;++q)load[machine][q]+=input[3+n+j*d+q];}std::int64_t makespan=0;for(std::size_t i=0;i<m;++i)for(std::size_t q=0;q<d;++q)makespan=std::max(makespan,load[i][q]);std::array<std::int64_t,FIELDS> staged{};std::size_t count=0;staged[count++]=m64;staged[count++]=d64;staged[count++]=makespan;for(std::size_t i=0;i<m;++i)for(std::size_t q=0;q<d;++q)staged[count++]=load[i][q];if(!output||capacity<8*count)return -2;for(std::size_t i=0;i<count;++i)put(output,8*i,staged[i]);return static_cast<std::int64_t>(8*count);}
